/**
 * Penyusun isi pemberitahuan hasil bacaan Resi.
 *
 * Duplikat dan penerima yang tidak sesuai kontrak hanya diumumkan server lewat
 * `frappe.msgprint` (juragan/gemini/extractor.py). Di desk itu menjadi dialog,
 * tapi di portal tidak pernah terbaca: `call()` frappe-ui membuang
 * `_server_messages` pada respons yang sukses. Karena itu pesannya disusun ulang
 * di sini dari ringkasan yang dikembalikan server (`ringkasan_hasil` di
 * doctype/resi/resi.py) — bentuk payload-nya sama untuk semua jalur unggah.
 */

const NADA = {
	merah: 'bg-ui-surface-red-100 text-ui-ink-red-600',
	kuning: 'bg-ui-surface-amber-100 text-ui-ink-amber-700',
	hijau: 'bg-ui-surface-green-100 text-ui-ink-green-600',
}

function ringkasanIsi(hasil) {
	return [
		hasil.nomor_referensi && `Ref ${hasil.nomor_referensi}`,
		hasil.nominal && `Rp ${Number(hasil.nominal).toLocaleString('id-ID')}`,
		hasil.metode,
	]
		.filter(Boolean)
		.join(' · ')
}

function susun(hasil) {
	const nomor = hasil.name ? `Resi ${hasil.name}` : ''
	if (hasil.status === 'Duplikat') {
		return {
			nada: 'merah',
			judul: 'Resi Duplikat',
			pesan: hasil.catatan_validasi || 'Bukti transfer ini sudah pernah dipakai.',
			ringkasan: nomor,
		}
	}
	if (hasil.status === 'Gagal') {
		return {
			nada: 'merah',
			judul: 'Bukti Transfer Ditolak',
			pesan: hasil.catatan_validasi || 'Isi bukti transfer tidak dapat dibaca.',
			ringkasan: nomor,
		}
	}
	if (hasil.catatan_validasi) {
		return {
			nada: 'kuning',
			judul: 'Resi Perlu Diperiksa',
			pesan: hasil.catatan_validasi,
			ringkasan: [nomor, ringkasanIsi(hasil)].filter(Boolean).join(' — '),
		}
	}
	return {
		nada: 'hijau',
		judul: 'Bukti Transfer Terbaca',
		pesan: nomor
			? `${nomor} dibuat dengan status ${hasil.status || '—'}.`
			: 'Bukti transfer berhasil dibaca.',
		ringkasan: ringkasanIsi(hasil),
	}
}

/** Isi dialog untuk satu ringkasan hasil dari server. */
export function popupHasilResi(hasil) {
	const isi = susun(hasil || {})
	return { ...isi, ikon: NADA[isi.nada] }
}

/** Isi dialog untuk kegagalan permintaan (bukan hasil bacaan). */
export function popupGagalResi(pesan, judul = 'Unggah Gagal') {
	return { nada: 'merah', judul, pesan, ikon: NADA.merah }
}
